import re, sys, difflib

def entries(path):
    """Map each ### heading to its body lines, ending at the next #, ##, or ### heading."""
    out, order, cur = {}, [], None
    fence = False
    for line in open(path, encoding="utf-8").read().splitlines():
        if line.startswith("```"):
            fence = not fence
        if not fence and re.match(r"#{1,3} ", line):
            cur = line if line.startswith("### ") else None
            if cur:
                out[cur] = []
                order.append(cur)
            continue
        if cur:
            out[cur].append(line)
    return out, order

old, old_order = entries(sys.argv[1])
new, new_order = entries(sys.argv[2])
print(f"entries: old {len(old)}, new {len(new)}")
print("\nonly in new:")
for h in new_order:
    if h not in old:
        print(f"  {h} ({len(new[h])} lines)")
print("\nkept, compared:")
for h in new_order:
    if h not in old:
        continue
    if old[h] == new[h]:
        print(f"  same     {h}")
    else:
        print(f"  DIFFERS  {h} (old {len(old[h])} lines, new {len(new[h])} lines)")
        d = list(difflib.unified_diff(old[h], new[h], lineterm="", n=0))[2:]
        for l in d[:40]:
            print("      " + l[:140])
        if len(d) > 40:
            print(f"      ... {len(d) - 40} more diff lines")
missing = [h for h in old_order if h not in new]
print(f"\nonly in old: {len(missing)}")
for h in missing:
    print(f"  {old_order.index(h) + 1:3} {h} ({len(old[h])} lines)")

