/// `--test-repo` is the target, with local remotes beside it and no
/// symlink, and a trailing slash does not move them.
#[test]
fn a_test_repo_is_a_path_with_its_remotes_beside_it() {
    for path in ["/t/one", "/t/one/"] {
        let mut args = args_for("unused");
        args.target = None;
        args.test_repo = Some(path.to_string());
        let params = InitParams::from(&args);
        assert!(!params.create_symlink);
        let plan = plan_init(&params, &cfg_empty()).unwrap();
        assert_eq!(plan.project_dir, PathBuf::from("/t/one"));
        assert_eq!(plan.name, "one");
        assert_eq!(plan.provisioner, Provisioner::LocalBareInit);
        assert_eq!(
            plan.work_bare_path,
            Some(PathBuf::from("/t/one.remotes/remote-work.git"))
        );
        assert_eq!(
            plan.agent.unwrap().bare_path,
            Some(PathBuf::from(
                "/t/one.remotes/remote-work.agent-session.git"
            ))
        );
    }
}

/// `--target` needs no value with `--test-repo`, and a plain init's
