#[test]
fn the_test_repo_flag_stands_in_for_the_target() {
    let cli = Cli::try_parse_from(["vc-x1", "init", "--test-repo", "./tmp/one"]).unwrap();
    let Commands::Init(args) = cli.command else {
        panic!("expected init");
    };
    assert_eq!(args.test_repo.as_deref(), Some("./tmp/one"));
