"""Check every relative markdown link and anchor across the template's files."""
import re
from pathlib import Path

ROOT = Path("/home/wink/data/prgs/rust/vc-x1-template-2")
LINK = re.compile(r"\]\(([^)\s]+)\)|^\[[^\]]+\]: (\S+)", re.M)


def slug(h):
    s = re.sub(r"`", "", h.strip().lower())
    s = re.sub(r"[^\w\- ]", "", s)
    return s.replace(" ", "-")


def anchors(path):
    out, fence = set(), False
    for line in path.read_text().splitlines():
        if line.startswith("```"):
            fence = not fence
        m = re.match(r"#{1,6} (.*)", line)
        if m and not fence:
            out.add(slug(m.group(1)))
    return out


bad = 0
checked = 0
for md in ROOT.rglob("*.md"):
    if md.name == "jj-tips.md":
        continue
    for m in LINK.finditer(md.read_text()):
        target = m.group(1) or m.group(2)
        if target.startswith(("http", "mailto")):
            continue
        file_part, _, frag = target.partition("#")
        dest = (md.parent / file_part).resolve() if file_part else md
        checked += 1
        if not dest.exists():
            print(f"{md.relative_to(ROOT)}: missing file {target}")
            bad += 1
        elif frag and dest.suffix == ".md" and frag not in anchors(dest):
            print(f"{md.relative_to(ROOT)}: missing anchor {target}")
            bad += 1
print(f"{checked} checked, {bad} bad")

